/**
 * 配置管理 Store
 * 用于管理后端配置的状态
 * 使用 Composition API 风格
 */

import { configAPI, skillAPI } from "@/lib/configApi.js";
import { getClientSettings } from "@/lib/clientSettings.js";
import { getAdminAvatarUrl } from "@/utils/avatar.js";
import { defineStore } from "pinia";
import { computed, ref } from "vue";

export const useConfigStore = defineStore("config", () => {
  // ========== State ==========

  // 完整配置
  const config = ref(null);

  // 适配器类型信息
  const adapterTypes = ref({
    types: [],
    adapters: [],
    count: 0,
  });

  // LLM 适配器
  const adapters = ref({});

  // 技能列表 (Pinia 级持久缓存，避免切 Tab 重复 loading)
  const skills = ref([]);
  const skillsLoaded = ref(false);

  // 模型列表 { provider: [{ owner, models }] }
  const models = ref({});

  // 模型元数据映射（Registry 规格决策）{ provider: { model: { matchSource, maxInput, watermark, vision, fc, reasoning } } }
  const modelsMeta = ref({});

  // 加载状态
  const loading = ref(false);

  // 是否需要重启服务
  const needRestart = ref(false);

  // 管理员验证码
  const adminCode = ref(localStorage.getItem("admin_code") || "");

  // 选中的适配器（用于批量操作）
  const selectedAdapters = ref([]);

  // ========== 客户端个人资料 (Pinia 响应式) ==========
  const getInitialProfile = () => {
    let initial = { name: "user", title: "Mio", avatar: null };
    try {
      const cached = localStorage.getItem("client_settings_profile");
      if (cached) {
        const parsed = JSON.parse(cached);
        if (parsed.name) initial.name = parsed.name;
        if (parsed.title) initial.title = parsed.title;
        if (parsed.avatar !== undefined) initial.avatar = parsed.avatar;
      }
    } catch (e) {}
    return initial;
  };

  const userProfile = ref(getInitialProfile());

  /**
   * 用户计算头像 URL
   */
  const userAvatarUrl = computed(() => {
    return getAdminAvatarUrl(userProfile.value.avatar);
  });

  // ========== Getters ==========

  /**
   * 获取所有启用的适配器
   */
  const enabledAdapters = computed(() => {
    const result = [];
    Object.entries(adapters.value).forEach(([type, instances]) => {
      instances.forEach((adapter, index) => {
        if (adapter.enable) {
          result.push({ type, index, ...adapter });
        }
      });
    });
    return result;
  });

  /**
   * 获取适配器总数
   */
  const totalAdapters = computed(() => {
    return Object.values(adapters.value).reduce(
      (sum, arr) => sum + arr.length,
      0,
    );
  });

  /**
   * 获取启用的适配器数量
   */
  const enabledAdaptersCount = computed(() => {
    let count = 0;
    Object.values(adapters.value).forEach((instances) => {
      instances.forEach((adapter) => {
        if (adapter.enable) count++;
      });
    });
    return count;
  });

  /**
   * 获取总模型数量
   */
  const totalModelsCount = computed(() => {
    let count = 0;
    Object.values(models.value).forEach((providerModels) => {
      if (Array.isArray(providerModels)) {
        providerModels.forEach((group) => {
          if (group.models && Array.isArray(group.models)) {
            count += group.models.length;
          }
        });
      }
    });
    return count;
  });

  // 插件数据
  const plugins = ref([]);

  /**
   * 获取可用插件总数
   */
  const totalPluginsCount = computed(() => {
    return plugins.value.length;
  });

  /**
   * 获取可用工具总数
   */
  const totalToolsCount = computed(() => {
    return plugins.value.reduce(
      (sum, plugin) => sum + (plugin.toolCount || 0),
      0,
    );
  });

  /**
   * 检查是否已认证（有管理员验证码）
   */
  const isAuthenticated = computed(() => !!adminCode.value);

  // ========== Actions ==========

  /**
   * 设置管理员验证码
   */
  function setAdminCode(code) {
    adminCode.value = code;
    configAPI.setAdminCode(code);
  }

  /**
   * 获取适配器类型信息
   */
  async function fetchAdapterTypes() {
    try {
      const response = await configAPI.getAdapterTypes();
      adapterTypes.value = response.data;
      return response.data;
    } catch (error) {
      console.error("获取适配器类型失败:", error);
      throw error;
    }
  }

  /**
   * 清除管理员验证码
   */
  function clearAdminCode() {
    adminCode.value = "";
    localStorage.removeItem("admin_code");
    configAPI.adminCode = "";
  }

  /**
   * 获取完整配置
   */
  async function fetchConfig() {
    loading.value = true;
    try {
      const response = await configAPI.getConfig();
      config.value = response.data;
      adapters.value = response.data.llm_adapters || {};
      // 同时获取 models 数据
      models.value = response.data.models || {};
      // 拉取模型元数据（Registry 规格，供管理界面展示 ctx/watermark/vision/matchSource）
      fetchModelMetadata();
      return response.data;
    } catch (error) {
      console.error("获取配置失败:", error);
      // 如果是认证失败，清除验证码
      if (
        error.message.includes("验证码") ||
        error.message.includes("访问被拒绝")
      ) {
        clearAdminCode();
      }
      throw error;
    } finally {
      loading.value = false;
    }
  }

  /**
   * 获取模型元数据映射（Registry 规格决策结果）
   */
  async function fetchModelMetadata() {
    try {
      const response = await configAPI.getModelsMeta();
      modelsMeta.value = response.data || {};
    } catch (error) {
      console.error("获取模型元数据失败:", error);
    }
  }

  /**
   * 从 socket 登录/推送写入模型规格元数据（按权限筛选，普通用户也能获得）
   */
  function setModelsMeta(meta) {
    if (!meta || typeof meta !== "object") return;
    modelsMeta.value = meta;
  }

  /**
   * 获取指定配置节点
   */
  async function fetchConfigSection(section) {
    try {
      const response = await configAPI.getConfigSection(section);
      if (config.value) {
        config.value[section] = response.data;
      }
      return response.data;
    } catch (error) {
      console.error(`获取配置节点 ${section} 失败:`, error);
      throw error;
    }
  }

  /**
   * 获取技能列表（带内存缓存）
   */
  async function fetchSkills(force = false) {
    if (!force && skillsLoaded.value && skills.value.length > 0) {
      return skills.value;
    }
    try {
      const res = await skillAPI.getSkills();
      if (res.success) {
        skills.value = res.data || [];
        skillsLoaded.value = true;
      }
      return skills.value;
    } catch (error) {
      console.error("获取技能列表失败:", error);
      return skills.value;
    }
  }

  /**
   * 重新同步技能库
   */
  async function reloadSkills() {
    try {
      const res = await skillAPI.reloadSkills();
      if (res.success) {
        skills.value = res.data || [];
        skillsLoaded.value = true;
      }
      return res;
    } catch (error) {
      console.error("同步技能库失败:", error);
      throw error;
    }
  }

  /**
   * 获取插件列表
   */
  async function fetchPlugins() {
    try {
      const result = await configAPI.request("/api/plugins");
      if (result.code === 0) {
        plugins.value = result.data.plugins || [];
        return result.data.plugins;
      } else {
        console.error("获取插件列表失败:", result.message);
        plugins.value = [];
        return [];
      }
    } catch (error) {
      console.error("获取插件列表失败:", error);
      plugins.value = [];
      throw error;
    }
  }

  /**
   * 更新完整配置
   */
  async function updateConfig(data) {
    try {
      const response = await configAPI.updateConfig(data);

      // 重新获取配置
      await fetchConfig();

      return response.data;
    } catch (error) {
      console.error("更新配置失败:", error);
      throw error;
    }
  }

  /**
   * 更新指定配置节点
   */
  async function updateConfigSection(section, data) {
    try {
      const response = await configAPI.updateConfigSection(section, data);

      // 更新本地状态
      if (config.value) {
        config.value[section] = data;
      }

      return response.data;
    } catch (error) {
      console.error(`更新配置节点 ${section} 失败:`, error);
      throw error;
    }
  }

  /**
   * 获取存储配置
   */
  async function fetchStorageConfig() {
    try {
      const response = await configAPI.getStorageConfig();
      if (config.value) {
        config.value.storage = response.data;
      }
      return response.data;
    } catch (error) {
      console.error("获取存储配置失败:", error);
      throw error;
    }
  }

  /**
   * 更新存储配置
   */
  async function updateStorageConfig(data) {
    try {
      const response = await configAPI.updateStorageConfig(data);
      if (config.value) {
        config.value.storage = data;
      }
      // 存储配置支持热更新，不需要设置 needRestart
      return response.data;
    } catch (error) {
      console.error("更新存储配置失败:", error);
      throw error;
    }
  }

  /**
   * 测试存储配置
   */
  async function testStorageConfig(data) {
    try {
      const response = await configAPI.testStorageConfig(data);
      return response.data;
    } catch (error) {
      console.error("测试存储配置失败:", error);
      throw error;
    }
  }

  /**
   * 添加适配器实例
   */
  async function addAdapter(type, data) {
    try {
      const response = await configAPI.addAdapter(type, data);

      // 更新本地状态（热更新，无需重启）
      await fetchConfig();
      models.value = response.data.models || {};

      return response.data;
    } catch (error) {
      console.error("添加适配器失败:", error);
      throw error;
    }
  }

  /**
   * 更新适配器实例
   */
  async function updateAdapter(type, instanceId, data) {
    const applyUpdateResponse = (response) => {
      // 用接口返回的完整适配器列表和模型列表直接更新本地状态
      if (response.data.llm_adapters) {
        adapters.value = response.data.llm_adapters;
      }
      if (response.data.models) {
        models.value = response.data.models;
      }
      return response.data;
    };

    try {
      const response = await configAPI.updateAdapter(type, instanceId, data);
      return applyUpdateResponse(response);
    } catch (error) {
      // 页面可能是在适配器类型迁移前打开的：ID 仍然有效，但 type 已变成
      // 真实类型。刷新一次配置后按全局稳定 ID 重试，不回退到数组下标。
      if (/适配器实例 ID .*不存在|适配器配置不存在/.test(error.message || "")) {
        try {
          await fetchConfig();
          const actualType = Object.entries(adapters.value).find(([, instances]) =>
            Array.isArray(instances) && instances.some((adapter) => adapter?.id === instanceId),
          )?.[0];
          if (actualType && actualType !== type) {
            const response = await configAPI.updateAdapter(actualType, instanceId, data);
            return applyUpdateResponse(response);
          }
        } catch (retryError) {
          console.error("按最新适配器类型重试更新失败:", retryError);
        }
      }
      console.error("更新适配器失败:", error);
      throw error;
    }
  }

  /**
   * 删除适配器实例
   */
  async function deleteAdapter(type, instanceId) {
    try {
      const response = await configAPI.deleteAdapter(type, instanceId);

      // 更新本地状态
      if (adapters.value[type]) {
        const position = adapters.value[type].findIndex(
          (adapter) => adapter.id === instanceId,
        );
        if (position >= 0) adapters.value[type].splice(position, 1);
      }
      models.value = response.data.models || {};

      return response.data;
    } catch (error) {
      console.error("删除适配器失败:", error);
      throw error;
    }
  }

  /**
   * 批量删除适配器实例
   */
  async function batchDeleteAdapters(adaptersList) {
    try {
      const results = await configAPI.batchDeleteAdapters(adaptersList);

      // 重新获取配置
      await fetchConfig();

      return results;
    } catch (error) {
      console.error("批量删除适配器失败:", error);
      throw error;
    }
  }

  /**
   * 批量启用/禁用适配器
   */
  async function batchToggleAdapters(adaptersList, enable) {
    const results = [];

    for (const adapter of adaptersList) {
      try {
        const adapterData = adapters.value[adapter.type]?.find(
          (item) => item.id === adapter.id,
        );
        if (!adapterData || !adapter.id) {
          throw new Error("批量操作失败：适配器缺少稳定实例 ID");
        }
        const updatedData = { ...adapterData, enable };

        await updateAdapter(
          adapter.type,
          adapter.id,
          updatedData,
        );
        results.push({ success: true, adapter });
      } catch (error) {
        results.push({ success: false, adapter, error: error.message });
      }
    }

    return results;
  }

  /**
   * 刷新所有模型列表
   */
  async function refreshAllModels() {
    try {
      const response = await configAPI.refreshAllModels();
      models.value = response.data.models || {};
      return response.data;
    } catch (error) {
      console.error("刷新模型列表失败:", error);
      throw error;
    }
  }

  /**
   * 刷新单个适配器实例模型列表
   */
  async function refreshAdapterModels(type, instanceId) {
    try {
      const response = await configAPI.refreshAdapterModels(type, instanceId);
      models.value = response.data.models || {};
      return response.data;
    } catch (error) {
      console.error("刷新适配器模型列表失败:", error);
      throw error;
    }
  }

  /**
   * 验证配置
   */
  async function validateConfig(data) {
    try {
      const response = await configAPI.validateConfig(data);
      return response.data;
    } catch (error) {
      console.error("验证配置失败:", error);
      throw error;
    }
  }

  /**
   * 重置配置
   */
  async function resetConfig() {
    try {
      const response = await configAPI.resetConfig();
      await fetchConfig();
      return response.data;
    } catch (error) {
      console.error("重置配置失败:", error);
      throw error;
    }
  }

  /**
   * 导出配置
   */
  async function exportConfig(filename) {
    try {
      await configAPI.exportConfig(filename);
    } catch (error) {
      console.error("导出配置失败:", error);
      throw error;
    }
  }

  /**
   * 导入配置
   */
  async function importConfig(file) {
    try {
      const configData = await configAPI.importConfig(file);
      return configData;
    } catch (error) {
      console.error("导入配置失败:", error);
      throw error;
    }
  }

  /**
   * 获取 OneBot 插件选项
   */
  async function fetchOneBotPlugins() {
    try {
      const response = await configAPI.getOneBotPlugins();
      return response.data;
    } catch (error) {
      console.error("获取 OneBot 插件选项失败:", error);
      throw error;
    }
  }

  /**
   * 获取 OneBot 连接与运行状态
   */
  async function fetchOneBotStatus() {
    try {
      const response = await configAPI.getOneBotStatus();
      return response.data;
    } catch (error) {
      console.error("获取 OneBot 连接状态失败:", error);
      throw error;
    }
  }

  /**
   * 切换适配器选中状态
   */
  function toggleAdapterSelection(type, instanceId) {
    const key = `${type}-${instanceId}`;
    const idx = selectedAdapters.value.findIndex(
      (a) => `${a.type}-${a.id}` === key,
    );

    if (idx > -1) {
      selectedAdapters.value.splice(idx, 1);
    } else {
      selectedAdapters.value.push({
        type,
        id: instanceId || "",
      });
    }
  }

  /**
   * 清空选中的适配器
   */
  function clearAdapterSelection() {
    selectedAdapters.value = [];
  }

  /**
   * 检查适配器是否被选中
   */
  function isAdapterSelected(type, instanceId) {
    const key = `${type}-${instanceId}`;
    return selectedAdapters.value.some((a) => `${a.type}-${a.id}` === key);
  }

  /**
   * 加载客户端设置 (localforage) 并更新 Pinia userProfile 响应式状态
   */
  async function loadClientSettings() {
    try {
      const settings = await getClientSettings();
      if (settings?.profile) {
        userProfile.value = {
          name: settings.profile.name || "user",
          title: settings.profile.title || "Mio",
          avatar:
            settings.profile.avatar !== undefined
              ? settings.profile.avatar
              : null,
        };
        try {
          localStorage.setItem(
            "client_settings_profile",
            JSON.stringify(userProfile.value),
          );
        } catch (e) {}
      }
      return settings;
    } catch (e) {
      console.warn("[configStore] 加载客户端设置失败:", e);
    }
  }

  /**
   * 更新并同步 Pinia 中的 userProfile 响应式状态
   */
  function updateUserProfile(profilePatch) {
    userProfile.value = {
      ...userProfile.value,
      ...profilePatch,
    };
    try {
      localStorage.setItem(
        "client_settings_profile",
        JSON.stringify(userProfile.value),
      );
    } catch (e) {}
  }

  // ========== 返回公开的 API ==========

  return {
    // State
    config,
    adapterTypes,
    adapters,
    models,
    modelsMeta,
    plugins,
    skills,
    skillsLoaded,
    loading,
    needRestart,
    adminCode,
    selectedAdapters,

    // Getters
    enabledAdapters,
    totalAdapters,
    enabledAdaptersCount,
    totalModelsCount,
    totalPluginsCount,
    totalToolsCount,
    isAuthenticated,
    userProfile,
    userAvatarUrl,

    // Actions
    setAdminCode,
    clearAdminCode,
    fetchAdapterTypes,
    fetchConfig,
    fetchConfigSection,
    fetchModelMetadata,
    setModelsMeta,
    fetchPlugins,
    fetchSkills,
    reloadSkills,
    updateConfig,
    updateConfigSection,
    fetchStorageConfig,
    updateStorageConfig,
    testStorageConfig,
    addAdapter,
    updateAdapter,
    deleteAdapter,
    batchDeleteAdapters,
    batchToggleAdapters,
    refreshAllModels,
    refreshAdapterModels,
    validateConfig,
    resetConfig,
    exportConfig,
    importConfig,
    fetchOneBotPlugins,
    fetchOneBotStatus,
    toggleAdapterSelection,
    clearAdapterSelection,
    isAdapterSelected,
    loadClientSettings,
    updateUserProfile,
  };
});
